import java.net.*;import java.nio.file.*;import java.io.*;
public class Loadout700ServerCheck {
 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS: "+s);}
 static final class Flat implements Battle.Ground {public boolean solid(int x,int y){return y>=170;}public int surface(int x,int y){return Math.max(y,170);}public void crater(int x,int y,int r){}}
 static Battle fresh(){Battle b=new Battle(new Flat());b.start(true);return b;}
 static void kit(Battle.Unit u,int a,int b,int c){u.kit[0]=a;u.kit[1]=b;u.kit[2]=c;}
 static void rules(){Battle b=fresh();Battle.Unit u=b.units[0];u.hp=1000;ok(b.item(1)&&u.hp==1500&&u.energy==90,"Heal consumes 150 energy and restores 500 HP");u.energy=240;ok(!b.item(1)&&u.energy==240,"Same slot cannot be used twice in one turn");b.next();b.next();ok(u.itemUsed==0&&b.item(1)&&u.hp==2000,"Slot refreshes on the owner's next turn");b=fresh();u=b.units[0];ok(!b.item(1)&&u.energy==240&&u.itemUsed==0,"Full HP heal does not consume energy or slot");ok(!b.item(-1)&&!b.item(3),"Invalid slots rejected");kit(u,2,3,4);b.configureTeam(2);u.hp=1000;b.units[2].hp=1200;b.units[1].hp=1000;ok(b.item(0)&&u.hp==1300&&b.units[2].hp==1500&&b.units[1].hp==1000&&u.energy==60,"Group heal affects living allies only and costs 180");
 b=fresh();u=b.units[0];kit(u,3,4,5);ok(b.item(0)&&b.freezeShot&&u.energy==90,"Freeze arms a server-computed projectile");Battle.Ball ball=b.make(45,60);ball.x=b.units[1].x*256;ball.y=(b.units[1].y-12)*256;b.impact(ball);ok(b.units[1].frozen==1&&b.units[1].hp<Battle.MAXHP,"Freeze applies only on an actual damaging hit");b.next();ok(b.units[1].frozen==2&&!b.input(),"Frozen target cannot move or use props during the skipped turn");for(int i=0;i<30;i++)b.tick();ok(b.active==0&&b.units[1].frozen==0,"Freeze skips exactly one own turn then expires");
 b=fresh();u=b.units[0];kit(u,3,4,5);ok(b.item(1)&&u.invisible==1&&u.energy==120,"Invisibility costs 120");b.next();ok(u.invisible==1,"Invisibility survives the opposing turn");b.next();ok(u.invisible==0,"Invisibility expires at the owner's next turn");int angle=u.angle,power=u.power;ok(b.item(2)&&u.assist&&u.energy==150&&u.angle==angle&&u.power==power,"Aim preview costs 90 without changing angle or power");b.next();b.next();ok(!u.assist,"Aim assistance expires and can be reused next turn");
 b=fresh();u=b.units[0];ok(b.item(0)&&b.fly&&u.energy==90&&b.make(45,70).fly,"Plane uses the existing offline flight physics");b=fresh();u=b.units[0];u.energy=89;kit(u,5,3,4);ok(!b.item(0)&&u.itemUsed==0,"Insufficient energy preserves the slot");b=fresh();ok(b.prop(0)&&b.extra==2&&b.units[0].energy==130,"Original Q buff is unchanged");b=fresh();u=b.units[0];u.rage=100;ok(b.prop(5)&&u.rage==0&&b.pow&&u.energy==240,"Original POW still consumes all rage immediately");ok(!Battle.validKit(new int[]{0,0,1})&&!Battle.validKit(new int[]{0,1,6})&&Battle.validKit(new int[]{3,4,5}),"Loadout validates unique item IDs");
 }
 public static void main(String[] args)throws Exception{rules();CloudStore.Memory store=new CloudStore.Memory();try(GunnyServer server=new GunnyServer(new InetSocketAddress("127.0.0.1",0),Path.of("backend/assets"),store)){var host=Matchmaking680Check.person(store,70);host.items=true;kitSession(host,3,4,5);var enemy=Matchmaking680Check.person(store,71);enemy.items=true;var room=Matchmaking680Check.room(server,host,null);room.members[1]=enemy;enemy.room=room.id;enemy.armed=true;room.refreshWaiting();room.start();ok(room.battle.units[0].kit[0]==3&&room.battle.units[0].kit[2]==5,"Server copies each player's selected loadout into battle");room.phase=1;room.battle.explicitHumans=true;room.battle.units[0].human=true;room.command(host,1,8,2);ok(room.battle.units[0].assist&&room.battle.units[0].energy==150,"Network item command is charged by authoritative Battle rules");room.command(host,2,8,2);ok(room.battle.units[0].energy==150,"Repeated network item cannot double-spend");room.battle.units[0].energy=0;room.command(host,3,8,0);ok(!room.battle.freezeShot,"Server rejects an item when energy was edited only on the client");room.chunkFrame();room.chunkFlush(false);ok(!room.chunks.isEmpty(),"Item state is included in buffered animation chunks");var legacy=Matchmaking680Check.person(store,72);var a=Matchmaking680Check.room(server,legacy,null);ok(!server.matchmaker.compatible(room,a),"Mixed item protocol rooms cannot match");}System.out.println("All loadout 7.0.0 server checks passed");}
 static void kitSession(GunnyServer.Session s,int a,int b,int c){s.kit[0]=a;s.kit[1]=b;s.kit[2]=c;}
}

